package id.velioragardens.veliorasuite.module.actionhouse;
import id.velioragardens.veliorasuite.VelioraSuite; import id.velioragardens.veliorasuite.api.VelioraModule; import id.velioragardens.veliorasuite.command.DisabledCommand; import org.bukkit.command.PluginCommand; import org.bukkit.configuration.file.YamlConfiguration; import org.bukkit.event.HandlerList; import org.bukkit.scheduler.BukkitTask; import java.io.File;
public final class ActionHouseModule implements VelioraModule { private final VelioraSuite plugin; private ActionHouseStore store; private ActionHouseGui gui; private BukkitTask expiry; private boolean enabled; public ActionHouseModule(VelioraSuite plugin){this.plugin=plugin;} public String getName(){return "actionhouse";} public void load(){plugin.saveResourceIfNotExists("modules/actionhouse.yml");YamlConfiguration c=YamlConfiguration.loadConfiguration(new File(plugin.getDataFolder(),"modules/actionhouse.yml"));store=new ActionHouseStore(plugin);store.load();gui=new ActionHouseGui(plugin,store,new ActionHouseEconomy(plugin),Math.max(1,c.getLong("listing-duration-days",14))*86400000L,Math.max(1,c.getDouble("slot-price",5000)));} public void enable(){enabled=true;PluginCommand command=plugin.getCommand("actionhouse");if(command!=null)command.setExecutor(new ActionHouseCommand(gui));plugin.getServer().getPluginManager().registerEvents(gui,plugin);expiry=plugin.getServer().getScheduler().runTaskTimer(plugin,store::expire,1200L,1200L);} public void disable(){enabled=false;if(expiry!=null)expiry.cancel();HandlerList.unregisterAll(gui);if(store!=null)store.save();PluginCommand command=plugin.getCommand("actionhouse");if(command!=null)command.setExecutor(new DisabledCommand(plugin,"VelioraActionHouse"));} public void reload(){disable();load();enable();} public boolean isEnabled(){return enabled;} }
